const int sensorPin = 2;  // Пин датчика (OUT)
const int ledPin = 13;    // Пин светодиода

void setup() {
  Serial.begin(9600);
  pinMode(sensorPin, INPUT);
  pinMode(ledPin, OUTPUT);
}

void loop() {
  int sensorValue = digitalRead(sensorPin);

  if (sensorValue == LOW) {       // LOW = объект обнаружен
    digitalWrite(ledPin, HIGH);   // Включить светодиод
    Serial.println("Объект! Светодиод ВКЛЮЧЕН");
  } else {                        // HIGH = пусто
    digitalWrite(ledPin, LOW);    // Выключить светодиод
    Serial.println("Пусто. Светодиод ВЫКЛЮЧЕН");
  }

  delay(100); // Небольшая пауза для стабильности
}
